task={}
files={R:f'{O}/{S}.jsonl'}
for i in ids: files[i]=f'{O}/{S}.children/{i}.jsonl'
def msgs(path):
    for line in open(path,'rb'):
        l=json.loads(line)
        if l.get('type')=='message' and isinstance(l['message'].get('content'),list):
            yield from l['message']['content']
skills={}
for sid,p in files.items():
    sk=set()
